"""Program 26 design package; no completion/issuance claims."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
WEEKS=['Establish a measurable agent baseline','Bound tools, memory and execution','Retrieve evidence and measure grounding','Compare search and critique strategies','Coordinate roles and recoverable state','Evaluate hostile and ordinary inputs','Strengthen reliability from failure evidence','Connect research to design decisions','Integrate and rehearse the capstone','Defend the system and its limitations']
LABS=[('Compare structured model adapters','Validate synthetic responses against one contract; report latency and token-budget assumptions without inventing provider measurements.'),('Baseline a tool decision','Compare a deterministic pipeline and bounded tool selection on identical synthetic requests.'),('Enforce tool budgets','Reject invalid tool inputs; demonstrate bounded retries and a hard step limit.'),('Measure memory tradeoffs','Compare task results with and without scoped memory; demonstrate deletion and isolation.'),('Benchmark retrieval candidates','Compare two proposed indexes on a labeled synthetic corpus; record recall and latency when executed.'),('Cite retrieved evidence','Route retrieval only when needed and abstain when the supplied corpus cannot support an answer.'),('Bound a search process','Compare a limited tree search with a linear baseline using observable decisions and outcomes, not hidden model reasoning.'),('Calibrate a critic','Use a fixed rubric to compare generator and critic outputs against human-labeled examples.'),('Specify specialist handoffs','Give researcher, analyst and writer separate contracts and record failures at each handoff.'),('Persist an approval checkpoint','Implement a recoverable state graph that cannot cross its action boundary without explicit approval.'),('Build a regression evidence set','Record task outcomes, observed tool steps, costs and traces; compare to the baseline.'),('Test hostile instructions','Inject synthetic adversarial instructions into retrieved content; compare blocked actions and task success before and after controls.')]
COMPETENCIES=['Implement a bounded agent with validated tools, scoped memory and termination tests.','Measure retrieval quality and trace each supported answer to evidence.','Compare coordination designs under failed tools, missing context and withheld approval.','Evaluate reliability, privacy and cost using reproducible tests and observable traces.','Deliver and defend a documented system with explicit limitations and human decision authority.']

def design():
 labs=[{'id':f'P26-L{i:02}','week':(i+1)//2,'title':t,'brief':b,'minutes':90,'status':'brief drafted; executable starter and solution pending','data':'Synthetic fixture required; data card must document provenance, fields and limitations.'} for i,(t,b) in enumerate(LABS,1)]
 return {'program':26,'title':'Agentic AI Systems Design — Live Intensive','brand':'Scholarion Academy','faculty':'Dr. Martins Donbruce Idahosa','state':'draft','weeks':10,'competencies':[{'id':'C'+str(i),'text':c} for i,c in enumerate(COMPETENCIES,1)],'modules':[{'week':i,'title':t,'outcomes':[{'id':f'P26-W{i}-O1','competency':'C'+str((i-1)%5+1),'text':'Demonstrate '+t.lower()+' with reproducible evidence.'},{'id':f'P26-W{i}-O2','competency':'C4','text':'Explain one failure, one limitation and the human approval boundary.'}],'activity':{'student':f'For {t.lower()}, define a synthetic scenario; build or model a bounded solution; record outputs and failed tests. Submit a 2–3-page APA-style Word/PDF report with code excerpts or diagrams, evidence and references. Proposed deadline: Sunday 11:59 PM in the published cohort time zone; no cohort dates configured.','instructor':f'Review {t.lower()} for reproducibility, evidence quality and safe boundaries. Check baseline comparability, withheld approval and unsupported claims. A specific worked solution and calibrated scoring guide are still required.'},'status':'design draft'} for i,t in enumerate(WEEKS,1)],'sessions':[],'labs':labs,'stretch':[{'title':t,'status':'optional design brief'} for t in ['Compare strict and permissive tool schemas','Test memory expiration','Measure retrieval abstention','Bound planner retries','Recover interrupted checkpoints','Estimate cost under doubled demand']],'capstone':'Choose a synthetic Academy support, research-evidence or permission-scoped code-review scenario. Build an end-to-end agent system and defend it in a ten-minute presentation. No external institution integration is authorized.','rubric':[{'criterion':c,'points':v} for c,v in [('Architecture and boundaries',20),('Typed tool integrations and coordination',20),('Baseline and evaluation evidence',25),('Guardrails, observability and cost',20),('Limitations and defense',15)]],'requirements':{'coreLabs':12,'quizCount':6,'quizMinimumPercent':70,'researchMemo':True,'capstoneThreshold':None,'presentationMinutes':10,'issueWithinDays':None,'accessMonths':None,'credit':False,'transferApproved':False},'researchMemo':'Choose a verified public research paper. Identify its question, method and limitations, then compare one design choice in your capstone against its evidence. Include an original discussion question and complete citation. Publication is blocked until faculty verifies authors, year, venue and source.','transfer':[{'to':1,'mapping':'Candidate overlap with source Weeks 1–8','approved':False},{'to':15,'mapping':'Candidate overlap with Weekends 3–5','approved':False}],'schedule':'Weeks 1–6: proposed live discussion and two 90-minute labs. Weeks 7–10: reliability, research, capstone clinics and defense. No dates, times, seats or recording availability have been published.','funding':'Non-credit professional training. No approval for federal student aid or military education benefits is recorded. Accepted payment methods are unconfigured.','notes':'','dependencyNotes':'Ten-week adaptation supersedes the source seven-week pacing. Transfer, late-enrollment deadline extensions, access duration and issue timing require approved policy.','publicationAllowed':False,'gaps':['Executed twelve domain labs and data cards','Six quiz banks and pass/cooldown implementation','Verified research citations and maintained tool/version licenses','Live calendar, time-zone display, recordings and support contacts','Approved capstone threshold, access period, issue timing and finance policies','Academic publication and credential-signing services']}
if __name__=='__main__':
 d=design();(ROOT/'dist/data/program26-design.json').write_text(json.dumps(d,indent=2),encoding='utf-8')
 print('Program 26 ten-week design, 12 lab briefs and activity editions generated.')
